/** TrueLine CAC product demo. Captures the actual app; no product UI is replaced.
 * Usage from repository root: node submission/cac-2026/demo/render-demo.mjs
 * Requirements: npm ci; Chromium; ffmpeg on PATH.
 * Generated files go in demo/output/; only the selected deliverables are tracked.
 */
import http from 'node:http';
