 let camera={x:88,y:115,scale:1.25};
 let group=null; const groups=[];
 async function capture(duration=1){const filename=String(frameNo++).padStart(5,'0')+'.jpg';await page.screenshot({path:path.join(frames,filename),type:'jpeg',quality:96});shots.push({file:filename,duration,start:elapsed,caption:currentCaption,camera:{...camera},group});elapsed+=duration;}
 async function transition(){if(!shots.length)return;const last=shots.at(-1).file;await page.evaluate(src=>{const t=document.getElementById('transition');t.style.backgroundImage='url('+src+')';t.style.display='block';t.style.opacity='1';},'/submission/cac-2026/demo/output/frames/'+last);for(let i=1;i<=8;i++){await page.evaluate(o=>document.getElementById('transition').style.opacity=o,1-i/8);await capture(.04);}await page.evaluate(()=>document.getElementById('transition').style.display='none');}
 async function startScene(name,text){group=name;groups.push({name,start:elapsed});if(currentCaption&&captions.length)captions.at(-1).end=elapsed;currentCaption=text;captions.push({start:elapsed,end:elapsed,text,group});await page.evaluate(({name,text})=>{document.getElementById('caption').textContent=text;document.getElementById('chapter').textContent=name;document.getElementById('card').classList.add('hidden');document.getElementById('cursor').style.display='none';},{name,text});await transition();}
 async function card({name,title,sub='',body='',eyebrow='',duration=7,hero=false}){group=name;groups.push({name,start:elapsed});if(currentCaption&&captions.length)captions.at(-1).end=elapsed;currentCaption='';await page.evaluate(({title,sub,body,eyebrow,hero})=>{const c=document.getElementById('card');c.className=hero?'hero':'';c.querySelector('h1').textContent=title;c.querySelector('.sub').textContent=sub;c.querySelector('.body').textContent=body;c.querySelector('.eyebrow').textContent=eyebrow;document.getElementById('cursor').style.display='none';},{title,sub,body,eyebrow,hero});captions.push({start:elapsed,end:elapsed+duration,text:[title,sub,body].filter(Boolean).join(' '),group});for(let i=1;i<=8;i++){const t=i/8;await page.evaluate(t=>{for(const e of document.querySelectorAll('#card .eyebrow,#card h1,#card .sub,#card .body,#heroart')){e.style.opacity=String(t);e.style.transform='translateY('+((1-t)*10)+'px)';}},t);await capture(.04);}await capture(duration-.32);}
 async function holdScene(duration){const start=groups.at(-1).start;if(elapsed<start+duration)await capture(start+duration-elapsed);}
 async function setCamera(region=null,maxScale=2.6,animate=false){const dest=region?(()=>{const scale=Math.min(1744/region.width,815/region.height,maxScale);return{x:88+(1744-region.width*scale)/2-region.x*scale,y:115+(815-region.height*scale)/2-region.y*scale,scale};})():{x:88,y:115,scale:1.25};const source={...camera};for(let i=1;i<=(animate?12:1);i++){const u=animate?i/12:1,t=u*u*(3-2*u);camera={x:source.x+(dest.x-source.x)*t,y:source.y+(dest.y-source.y)*t,scale:source.scale+(dest.scale-source.scale)*t};await page.evaluate(c=>{const f=document.getElementById('appframe');f.style.left=c.x+'px';f.style.top=c.y+'px';f.style.transform='scale('+c.scale+')';document.getElementById('cursor').style.display='none';},camera);if(animate)await capture(.04);}await sleep(35);}
 async function focusPreview(){const r=await app.evaluate(()=>{const r=document.querySelector('.trace-stage').getBoundingClientRect();return{x:r.x-18,y:r.y-18,width:r.width+36,height:r.height+36};});await setCamera(r);}
 async function focusUnderlay(){const r=await app.evaluate(()=>{const u=m.App.doc.underlay,a=m.toScreen({x:u.x,y:u.y}),b=m.toScreen({x:u.x+u.wMM,y:u.y+u.hMM}),c=document.getElementById('cvOverlay').getBoundingClientRect();return{x:c.left+a.x,y:c.top+a.y,width:b.x-a.x,height:b.y-a.y};});await setCamera(r,4.8);}
 async function focusPreviewImage(){const r=await app.evaluate(()=>{const c=document.querySelector('.trace-stage canvas'),r=c.getBoundingClientRect(),s=Math.min(r.width/c.width,r.height/c.height),w=c.width*s,h=c.height*s;return{x:r.x+(r.width-w)/2,y:r.y+(r.height-h)/2,width:w,height:h};});await setCamera(r,4.8);}
 async function cursor(x,y,down=false){await page.evaluate(({x,y,down})=>{const e=document.getElementById('cursor');e.style.display='block';e.style.left=x+'px';e.style.top=y+'px';e.style.background=down?'#74d5e84d':'transparent';},{x,y,down});}
 async function hideCursor(){await page.evaluate(()=>document.getElementById('cursor').style.display='none');}
 async function move(x,y,{steps=6,record=true}={}){const start=await page.evaluate(()=>{const e=document.getElementById('cursor');return{x:parseFloat(e.style.left)||960,y:parseFloat(e.style.top)||480};});for(let i=1;i<=steps;i++){const u=i/steps,a=u*u*(3-2*u),nx=start.x+(x-start.x)*a,ny=start.y+(y-start.y)*a;await page.mouse.move(nx,ny);await cursor(nx,ny);if(record)await capture(.045);}}
 async function box(el){await el.evaluate(e=>e.scrollIntoView({block:'nearest'}));const r=await el.evaluate(e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height};});return{x:camera.x+r.x*camera.scale,y:camera.y+r.y*camera.scale,width:r.width*camera.scale,height:r.height*camera.scale};}
 async function click(selector,{hold=.35,record=true}={}){const el=await app.$(selector);assert(el,selector);const b=await box(el);await move(b.x+b.width/2,b.y+b.height/2,{record});await page.mouse.click(b.x+b.width/2,b.y+b.height/2);await sleep(100);if(record)await capture(hold);}
 async function clickText(text,{hold=.4,record=true}={}){const handle=await app.evaluateHandle(text=>[...document.querySelectorAll('button')].find(b=>b.textContent.trim()===text&&b.getClientRects().length),text);const el=handle.asElement();assert(el,'Button '+text);const b=await box(el);await move(b.x+b.width/2,b.y+b.height/2,{record});await page.mouse.click(b.x+b.width/2,b.y+b.height/2);await sleep(100);if(record)await capture(hold);}
 async function world(p){const r=await app.evaluate(p=>{const r=document.getElementById('cvOverlay').getBoundingClientRect(),s=m.toScreen(p);return{x:r.left+s.x,y:r.top+s.y};},p);return{x:camera.x+r.x*camera.scale,y:camera.y+r.y*camera.scale};}
 async function pointClick(p){const pos=await world(p);await move(pos.x,pos.y);await page.mouse.click(pos.x,pos.y);await capture(.7);}
 async function editPoint(x,y){const p=await app.evaluate(({x,y})=>{const c=document.querySelector('.trace-stage canvas'),r=c.getBoundingClientRect(),s=Math.min(r.width/c.width,r.height/c.height);return{x:r.left+(r.width-c.width*s)/2+x*s,y:r.top+(r.height-c.height*s)/2+y*s};},{x,y});return{x:camera.x+p.x*camera.scale,y:camera.y+p.y*camera.scale};}
 // Original illustrated mounting plate: asymmetric profile, three bolt holes and a slot.
 const outer=[];let last={x:14,y:0};outer.push({...last});
 function line(x,y){const from=last,n=Math.max(6,Math.ceil(Math.hypot(x-from.x,y-from.y)/1.5));for(let i=1;i<=n;i++)outer.push({x:from.x+(x-from.x)*i/n,y:from.y+(y-from.y)*i/n});last={x,y};}
 function arc(cx,cy,r,a0,a1){const n=Math.max(12,Math.ceil(Math.abs(a1-a0)*r/1.2));for(let i=1;i<=n;i++){const a=a0+(a1-a0)*i/n;outer.push({x:cx+r*Math.cos(a),y:cy+r*Math.sin(a)});}last=outer.at(-1);}
 line(106,0);arc(106,6,6,-Math.PI/2,0);line(112,24);arc(106,24,6,0,Math.PI/2);line(76,30);arc(76,36,6,-Math.PI/2,-Math.PI);line(70,74);arc(64,74,6,0,Math.PI/2);line(6,80);arc(6,74,6,Math.PI/2,Math.PI);line(0,14);arc(14,14,14,Math.PI,Math.PI*1.5);
 const holes=[[16,16,5],[96,15,5],[16,64,5]].map(([x,y,r])=>Array.from({length:97},(_,i)=>({x:x+r*Math.cos(i/96*Math.PI*2),y:y+r*Math.sin(i/96*Math.PI*2)})));
 const slot=[];for(let i=0;i<=32;i++){const a=Math.PI+i/32*Math.PI;slot.push({x:42+5*Math.cos(a),y:43+5*Math.sin(a)});}for(let i=1;i<=16;i++)slot.push({x:47,y:43+20*i/16});for(let i=1;i<=32;i++){const a=i/32*Math.PI;slot.push({x:42+5*Math.cos(a),y:63+5*Math.sin(a)});}for(let i=1;i<=16;i++)slot.push({x:37,y:63-20*i/16});
 const part={outer,holes,slot,scale:7,ox:118,oy:100,width:1020,height:760};
 const raster=await page.evaluate(part=>{const c=document.createElement('canvas');c.width=part.width;c.height=part.height;const g=c.getContext('2d');g.fillStyle='#e8ecec';g.fillRect(0,0,c.width,c.height);
 function path(points){g.beginPath();for(let i=0;i<points.length;i++){const p=points[i],x=part.ox+p.x*part.scale,y=part.oy+p.y*part.scale;i?g.lineTo(x,y):g.moveTo(x,y);}g.closePath();}
 const metal=g.createLinearGradient(160,100,850,700);metal.addColorStop(0,'#4e6571');metal.addColorStop(.5,'#718892');metal.addColorStop(1,'#3b505c');path(part.outer);g.fillStyle=metal;g.shadowColor='#182a3540';g.shadowBlur=16;g.shadowOffsetY=8;g.fill();g.shadowColor='transparent';g.strokeStyle='#334955';g.lineWidth=2;g.stroke();
 g.save();path(part.outer);g.clip();g.strokeStyle='#d6e5eb16';g.lineWidth=1;for(let y=0;y<c.height;y+=6){g.beginPath();g.moveTo(0,y);g.lineTo(c.width,y+40);g.stroke();}g.restore();
 g.fillStyle='#e8ecec';for(const points of [...part.holes,part.slot]){path(points);g.fill();g.strokeStyle='#334955';g.lineWidth=2;g.stroke();}
 return c.toDataURL().split(',')[1];},part);
 const fixture=path.join(out,'sample-mounting-plate.png');await fs.writeFile(fixture,Buffer.from(raster,'base64'));
 await startScene('01 / TRACE THE PROFILE','Lay the part on a drawing pad and begin tracing.');
 await click('#fileBtn');await click('[data-cmd="upload-image"]');await(await app.$('#imagePick')).uploadFile(fixture);await app.waitForFunction(()=>m.getUnderlayImg()?.naturalWidth===1020);await app.waitForFunction(()=>document.getElementById('toast').hidden,{timeout:15000});
 await click('[data-tool="freehand"]',{record:false});
 const map=await app.evaluate(()=>({...m.App.doc.underlay}));
 function worldPart(p){return{x:map.x+(part.ox+p.x*part.scale)*map.wMM/part.width,y:map.y+(part.oy+p.y*part.scale)*map.hMM/part.height};}
 const region=await app.evaluate(({a,b})=>{const r=document.getElementById('stack').getBoundingClientRect(),p=m.toScreen(a),q=m.toScreen(b);return{x:r.x+p.x-30,y:r.y+p.y-30,width:q.x-p.x+60,height:q.y-p.y+60};},{a:worldPart({x:-3,y:-3}),b:worldPart({x:115,y:83})});
 await hideCursor();await capture(.7);await setCamera(region,2.2,true);
 async function trace(points,{visible=true,preview=.65}={}){const before=await app.evaluate(()=>m.App.doc.entities.length);const noisy=points.map((p,i)=>{if(i===0||i===points.length-1)return p;return{x:p.x+Math.sin(i*1.71)*.07,y:p.y+Math.sin(i*.63)*.07};});let pos=await world(worldPart(noisy[0]));await move(pos.x,pos.y,{record:false});await page.mouse.down();
 for(let i=1;i<noisy.length;i++){pos=await world(worldPart(noisy[i]));await page.mouse.move(pos.x,pos.y);await cursor(pos.x,pos.y,true);if(visible&&i%3===0)await capture(.045);}await page.mouse.up();await hideCursor();assert(await app.evaluate(()=>Boolean(m.App.tools.get('freehand').pending)),'Actual stroke review');await capture(preview);await setCamera(null,2.6,visible);await clickText('Accept',{record:visible});assert((await app.evaluate(()=>m.App.doc.entities.length))>before,'Trace committed');await hideCursor();}
 await trace(outer);await holdScene(14);
