 const heroSrc='/submission/cac-2026/demo/output/';await page.evaluate(src=>{document.getElementById('partimage').src=src+'part-reference.png';document.getElementById('cadimage').src=src+'part-cad-outline.png';},heroSrc);await page.evaluate(()=>Promise.all([...document.querySelectorAll('#heroart img')].map(i=>i.decode())));

